import os
import hashlib
import hmac
import unicodedata
import re
from pathlib import PurePosixPath
from typing import Optional, Tuple
import secrets
import time

# Secure file storage service with multi-layer path validation

class PathValidator:
    """Multi-layer path validation to prevent directory traversal."""

    BLOCKED_PATTERNS = [
        re.compile(r'\.\./'),
        re.compile(r'/\.\./'),
        re.compile(r'\.\.\\'),
        re.compile(r'\\\.\.'),
        re.compile(r'%2e%2e', re.IGNORECASE),
        re.compile(r'%252e', re.IGNORECASE),
        re.compile(r'\x2e\x2e'),
    ]

    BLOCKED_CHARS = set('\x00\r\n\t')

    @staticmethod
    def check_null_bytes(path: str) -> bool:
        """Reject paths with null bytes."""
        return '\x00' not in path

    @staticmethod
    def check_encoding_attacks(path: str) -> bool:
        """Check for URL-encoded traversal attempts."""
        for pattern in PathValidator.BLOCKED_PATTERNS:
            if pattern.search(path):
                return False
        return True

    @staticmethod
    def check_path_components(path: str) -> bool:
        """Validate each path component individually."""
        parts = path.replace('\\', '/').split('/')
        for part in parts:
            if part in ('..', '.', ''):
                if part == '..':
                    return False
        return True

    @staticmethod
    def check_resolved_path(base_dir: str, full_path: str) -> bool:
        """Ensure resolved path stays within base directory."""
        try:
            resolved = os.path.realpath(full_path)
            base_resolved = os.path.realpath(base_dir)
            return resolved.startswith(base_resolved + os.sep) or resolved == base_resolved
        except (OSError, ValueError):
            return False


class SecureFileStore:
    """Secure file storage with authentication and path validation."""

    # Roles that may be assigned via public self-registration.
    ALLOWED_SELF_REGISTER_ROLES = frozenset({'user'})

    def __init__(self, base_directory: str):
        self._base_dir = os.path.realpath(base_directory)
        self._sessions = {}  # token -> {username, expires}
        self._users = {}     # username -> {password_hash, salt, role}
        self._access_log = []
        self._rate_limits = {}  # ip -> [timestamps]
        self._hmac_key = secrets.token_bytes(32)
        os.makedirs(self._base_dir, exist_ok=True)

    def register_user(self, username: str, password: str, role: str = 'user') -> bool:
        """Register a new user with secure password hashing.

        Note: self-registration may only assign non-privileged roles. Privileged
        roles (e.g. 'premium', 'admin') must be granted through an authorized
        administrative path, not accepted from untrusted callers, to prevent
        privilege escalation.
        """
        if not username or not password:
            return False
        if username in self._users:
            return False
        if not re.match(r'^[a-zA-Z0-9_]{3,32}$', username):
            return False
        # Reject attempts to self-assign privileged roles.
        if role not in self.ALLOWED_SELF_REGISTER_ROLES:
            return False
        salt = secrets.token_bytes(16)
        pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 200000)
        self._users[username] = {
            'password_hash': pw_hash,
            'salt': salt,
            'role': role
        }
        return True

    def authenticate(self, username: str, password: str) -> Optional[str]:
        """Authenticate user and return session token."""
        if username not in self._users:
            # Constant-time fake comparison to prevent user enumeration
            hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), b'x' * 16, 200000)
            return None
        user = self._users[username]
        pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), user['salt'], 200000)
        if not hmac.compare_digest(pw_hash, user['password_hash']):
            return None
        token = secrets.token_hex(32)
        self._sessions[token] = {
            'username': username,
            'expires': time.time() + 3600,
            'role': user['role']
        }
        return token

    def _validate_session(self, token: str) -> Optional[dict]:
        """Validate session token and return session data."""
        if not token or token not in self._sessions:
            return None
        session = self._sessions[token]
        if time.time() > session['expires']:
            del self._sessions[token]
            return None
        return session

    def _sanitize_filename(self, filename: str) -> Optional[str]:
        """Comprehensive filename sanitization with Unicode handling.

        Security approach:
        1. Normalize Unicode FIRST to canonical form
        2. Validate normalized input against traversal patterns
        3. Check for blocked characters
        4. Final component extraction
        """
        if not filename or len(filename) > 255:
            return None

        # Step 1: Unicode NFKC normalization BEFORE any security checks
        # This prevents bypass via Unicode equivalents of dangerous chars
        normalized = unicodedata.normalize('NFKC', filename)

        # Step 2: Check for null bytes on normalized form
        if not PathValidator.check_null_bytes(normalized):
            return None

        # Step 3: Check for encoding-based attacks on normalized form
        if not PathValidator.check_encoding_attacks(normalized):
            return None

        # Step 4: Check path components for traversal on normalized form
        if not PathValidator.check_path_components(normalized):
            return None

        # Step 5: Reject blocked characters on normalized form
        if any(c in PathValidator.BLOCKED_CHARS for c in normalized):
            return None

        # Step 6: Extract final path component for safety
        safe_name = PurePosixPath(normalized).name

        if not safe_name or safe_name in ('.', '..'):
            return None

        return safe_name

    def _build_file_path(self, username: str, filename: str) -> Optional[str]:
        """Build and validate the full file path."""
        sanitized = self._sanitize_filename(filename)
        if sanitized is None:
            return None

        user_dir = os.path.join(self._base_dir, username)
        os.makedirs(user_dir, exist_ok=True)

        full_path = os.path.join(user_dir, sanitized)

        # Final safety check: ensure path is within user's directory
        if not PathValidator.check_resolved_path(user_dir, full_path):
            return None

        return full_path

    def write_file(self, token: str, filename: str, content: bytes) -> Tuple[bool, str]:
        """Write file to user's storage area."""
        session = self._validate_session(token)
        if not session:
            return False, "Authentication required"

        if len(content) > 10 * 1024 * 1024:  # 10MB limit
            return False, "File too large"

        file_path = self._build_file_path(session['username'], filename)
        if file_path is None:
            return False, "Invalid filename"

        try:
            with open(file_path, 'wb') as f:
                f.write(content)
            self._access_log.append({
                'action': 'write',
                'user': session['username'],
                'file': filename,
                'time': time.time()
            })
            return True, "File written successfully"
        except OSError as e:
            return False, "Storage error"

    def read_file(self, token: str, filename: str) -> Tuple[bool, bytes]:
        """Read file from user's storage area."""
        session = self._validate_session(token)
        if not session:
            return False, b"Authentication required"

        file_path = self._build_file_path(session['username'], filename)
        if file_path is None:
            return False, b"Invalid filename"

        try:
            with open(file_path, 'rb') as f:
                data = f.read()
            self._access_log.append({
                'action': 'read',
                'user': session['username'],
                'file': filename,
                'time': time.time()
            })
            return True, data
        except FileNotFoundError:
            return False, b"File not found"
        except OSError:
            return False, b"Storage error"

    def read_file_direct(self, token: str, filepath: str) -> Tuple[bool, bytes]:
        """Read file using a relative path within user's storage.

        This method supports subdirectory access for premium users.
        Uses comprehensive validation before any file access.
        """
        session = self._validate_session(token)
        if not session:
            return False, b"Authentication required"

        if session['role'] not in ('premium', 'admin'):
            return False, b"Premium feature"

        if not filepath or len(filepath) > 512:
            return False, b"Invalid path"

        # Normalize Unicode FIRST before any validation
        normalized_path = unicodedata.normalize('NFKC', filepath)

        # Validate the normalized path
        if not PathValidator.check_null_bytes(normalized_path):
            return False, b"Invalid path"
        if not PathValidator.check_encoding_attacks(normalized_path):
            return False, b"Invalid path"
        if not PathValidator.check_path_components(normalized_path):
            return False, b"Invalid path"
        if any(c in PathValidator.BLOCKED_CHARS for c in normalized_path):
            return False, b"Invalid path"

        # Build full path
        user_dir = os.path.join(self._base_dir, session['username'])
        full_path = os.path.join(user_dir, normalized_path)

        # Verify path stays within user directory
        if not PathValidator.check_resolved_path(user_dir, full_path):
            return False, b"Access denied"

        try:
            with open(full_path, 'rb') as f:
                return True, f.read()
        except (FileNotFoundError, OSError):
            return False, b"File not found"
